function pinStorageKey(){return me?"rc_pin_hash_"+me.id:""}
function pinRecordKey(){return me?"rc_pin_secure_"+me.id:""}
async function hashPin(pin){const data=new TextEncoder().encode(String(pin));const hash=await crypto.subtle.digest("SHA-256",data);return btoa(String.fromCharCode(...new Uint8Array(hash)))}
async function derivePin(pin,salt){const key=await crypto.subtle.importKey("raw",new TextEncoder().encode(String(pin)),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",salt:new Uint8Array(salt),iterations:150000,hash:"SHA-256"},key,256);return btoa(String.fromCharCode(...new Uint8Array(bits)))}
function randomPinSalt(){const a=new Uint8Array(16);crypto.getRandomValues(a);return btoa(String.fromCharCode(...a))}
async function savePin(pin){const salt=randomPinSalt(),bytes=Uint8Array.from(atob(salt),c=>c.charCodeAt(0)),hash=await derivePin(pin,bytes);localStorage.setItem(pinRecordKey(),JSON.stringify({v:2,salt,hash}))}
async function verifyPin(pin){try{const raw=localStorage.getItem(pinRecordKey());if(raw){const rec=JSON.parse(raw),bytes=Uint8Array.from(atob(rec.salt),c=>c.charCodeAt(0));return (await derivePin(pin,bytes))===rec.hash}const legacy=localStorage.getItem(pinStorageKey());if(!legacy)return false;const ok=(await hashPin(pin))===legacy;if(ok)await savePin(pin);return ok}catch(e){return false}}
function clearPin(){try{localStorage.removeItem(pinRecordKey());localStorage.removeItem(pinStorageKey())}catch(e){}}
function pinSheet(){const has=hasPin();sheet(`<h2>${has?"تغيير أو إلغاء قفل التطبيق":"تفعيل قفل التطبيق"}</h2><p class="lab">سيطلب التطبيق رمز PIN عند العودة إليه، ولن يتم تسجيل الخروج تلقائيًا.</p>${has?`<input id="pc" type="password" inputmode="numeric" maxlength="6" class="pin-lock-input" placeholder="الرمز الحالي">`:""}<input id="pn" type="password" inputmode="numeric" maxlength="6" class="pin-lock-input" placeholder="PIN جديد"><input id="pnc" type="password" inputmode="numeric" maxlength="6" class="pin-lock-input" placeholder="تأكيد PIN"><div class="msg" id="pm"></div><button class="btn" id="ps">${has?"حفظ الرمز الجديد":"تفعيل القفل"}</button>${has?`<button class="btn g" id="pd">إلغاء قفل التطبيق</button><button class="linkbtn" id="pr" type="button">نسيت الرمز؟ إرسال رابط إلى البريد</button>`:""}`);$("#ps").onclick=async()=>{const m=$("#pm"),n=$("#pn").value,c=$("#pnc").value;if(!/^\d{6}$/.test(n)||n!==c){m.textContent="أدخل رمزًا من 6 أرقام متطابقًا";return}if(has&&!await verifyPin($("#pc").value)){m.textContent="الرمز الحالي غير صحيح";return}await savePin(n);localStorage.removeItem("rc_pin_away_"+me.id);sheet(null);m&&render()};if($("#pd"))$("#pd").onclick=()=>{sheet(`<div class="permission-card" style="text-align:right"><div class="permission-icon">${I("lock-keyhole",34)}</div><h2 style="text-align:center">هل أنت متأكد من إلغاء القفل؟</h2><p style="text-align:center">أدخل رمز PIN الحالي لتأكيد إلغاء قفل التطبيق.</p><input id="unlockConfirmPin" class="pin-lock-input" type="password" inputmode="numeric" maxlength="6" autocomplete="off" placeholder="رمز PIN الحالي" style="text-align:center;direction:ltr;letter-spacing:.25em"><div class="msg" id="unlockConfirmMsg"></div><button class="btn" id="unlockConfirmBtn">تأكيد إلغاء القفل</button><button class="btn g" onclick="sheet(null)">إلغاء</button></div>`);const b=$("#unlockConfirmBtn"),inp=$("#unlockConfirmPin"),m=$("#unlockConfirmMsg");const confirmUnlock=async()=>{if(!/^\d{6}$/.test(inp.value)){m.textContent="أدخل رمز PIN مكوّنًا من 6 أرقام";return}b.disabled=true;try{if(!await verifyPin(inp.value)){m.textContent="رمز PIN غير صحيح";inp.value="";return}clearPin();localStorage.removeItem("rc_pin_away_"+me.id);sheet(`<div class="success-state"><div class="success-icon">${I("lock-open",34)}</div><h2>تم إلغاء قفل التطبيق</h2><p>لن يطلب التطبيق رمز PIN عند العودة إليه.</p><button class="btn" onclick="sheet(null);render()">حسنًا</button></div>`)}finally{b.disabled=false}};b.onclick=confirmUnlock;inp.oninput=()=>{if(inp.value.length===6)confirmUnlock()};setTimeout(()=>inp.focus(),80)};if($("#pr"))$("#pr").onclick=async()=>{const m=$("#pm");try{m.style.color="var(--mute)";m.textContent="استعادة رمز PIN تحتاج التحقق من الهوية عبر الإدارة؛ لا يتم إرسال رابط غير مهيأ."}catch(e){m.textContent="تعذر إرسال الرابط؛ حاول مرة أخرى"}}}
function confirmLogout(){sheet(`<div class="logout-confirm"><div class="logout-icon">${I("log-out",30)}</div><h2>تسجيل الخروج</h2><p>هل أنت متأكد تريد تسجيل الخروج؟<br>سيتم إغلاق الجلسة الحالية.</p><div class="logout-actions"><button class="btn g" onclick="sheet(null)">إلغاء</button><button class="btn danger" onclick="sheet(null);logout()">تسجيل الخروج</button></div></div>`)}
function hasPin(){return !!(me&&(localStorage.getItem(pinRecordKey())||localStorage.getItem(pinStorageKey())))}
const PIN_AWAY_LIMIT=5*60*1000;
function pinAwayKey(){return me?"rc_pin_away_"+me.id:""}
function markPinAway(){if(!hasPin())return;hiddenAt=Date.now();try{localStorage.setItem(pinAwayKey(),String(hiddenAt))}catch(e){}}
function checkPinAway(){if(!hasPin())return;let away=0;try{const k=pinAwayKey();away=Number(localStorage.getItem(k)||0);localStorage.removeItem(k)}catch(e){}hiddenAt=0;if(away&&Date.now()-away>=PIN_AWAY_LIMIT)lockApp()}
async function lockApp(){if(appLocked||!hasPin()||!me)return;appLocked=true;sheet(null);const old=$("#pinlock");if(old)old.remove();const o=document.createElement("div");o.id="pinlock";o.className="pin-lock";o.innerHTML=`<div class="pin-lock-card"><img src="${LOGO_URL}" alt="الرفاه كاش"><h2>التطبيق مقفل</h2><p>أدخل رمز PIN المكوّن من 6 أرقام للمتابعة</p><input id="unlockPin" class="pin-lock-input" type="password" inputmode="numeric" maxlength="6" autocomplete="off" placeholder="••••••"><div class="msg" id="unlockMsg" style="color:#ffd6d6"></div><button class="btn" id="unlockBtn">فتح التطبيق</button></div>`;document.body.appendChild(o);const inp=$("#unlockPin"),btn=$("#unlockBtn"),msg=$("#unlockMsg");const unlock=async()=>{if(Date.now()<pinBlockedUntil){msg.textContent="تم إيقاف المحاولة مؤقتًا؛ انتظر قليلًا ثم حاول مرة أخرى";return}if(!/^\d{6}$/.test(inp.value)){msg.textContent="أدخل 6 أرقام";return}btn.disabled=true;try{if(!await verifyPin(inp.value)){pinFailCount++;msg.textContent="رمز PIN غير صحيح";inp.value="";if(pinFailCount>=5){pinBlockedUntil=Date.now()+30000;pinFailCount=0;msg.textContent="محاولات كثيرة غير صحيحة؛ أعد المحاولة بعد 30 ثانية"}return}pinFailCount=0;appLocked=false;o.remove()}finally{btn.disabled=false}};btn.onclick=unlock;inp.oninput=()=>{if(inp.value.length===6)unlock()};setTimeout(()=>inp.focus(),50)}
document.addEventListener("visibilitychange",()=>{if(document.hidden)markPinAway();else checkPinAway()})
window.addEventListener("pagehide",markPinAway)
window.addEventListener("pageshow",()=>{if(document.visibilityState==="visible")checkPinAway()})
