async function saveDataUrlFile(data,name,mime){
 if(!data)return false;
 const parts=String(data).split(","),b64=parts.length>1?parts[1]:parts[0],type=mime||((parts[0].match(/data:([^;]+)/)||[])[1])||"application/octet-stream";
 if(window.AlrafahAndroid&&typeof window.AlrafahAndroid.saveFile==="function"){
  const ok=window.AlrafahAndroid.saveFile(name||"alrafah-cash-file",type,b64);
  if(ok){const el=$("#downloadMsg");if(el)el.textContent="تم حفظ الملف في مجلد التنزيلات"}return ok;
 }
 try{const a=document.createElement("a");a.href=data;a.download=name||"alrafah-cash-file";a.click();return true}catch(e){return false}
}
async function shareDataUrlFile(data,name,mime){
 if(!data)return false;
 const parts=String(data).split(","),b64=parts.length>1?parts[1]:parts[0],type=mime||((parts[0].match(/data:([^;]+)/)||[])[1])||"application/octet-stream";
 if(window.AlrafahAndroid&&typeof window.AlrafahAndroid.shareFile==="function")return window.AlrafahAndroid.shareFile(name||"alrafah-cash-file",type,b64);
 try{const r=await fetch(data),blob=await r.blob(),f=new File([blob],name||"alrafah-cash-file",{type});if(navigator.share&&(!navigator.canShare||navigator.canShare({files:[f]}))){await navigator.share({files:[f],title:"الرفاه كاش"});return true}}catch(e){}return false;
}
async function saveBlobFile(blob,name,mime){return await new Promise(resolve=>{const r=new FileReader();r.onload=async()=>resolve(await saveDataUrlFile(r.result,name,mime||blob.type));r.onerror=()=>resolve(false);r.readAsDataURL(blob)})}
async function shareBlobFile(blob,name,mime){return await new Promise(resolve=>{const r=new FileReader();r.onload=async()=>resolve(await shareDataUrlFile(r.result,name,mime||blob.type));r.onerror=()=>resolve(false);r.readAsDataURL(blob)})}
