async function readProof(file){if(!file)return null;if(file.size>2500000)throw Error("حجم الملف كبير؛ الحد الأقصى 2.5MB");if(file.type.startsWith("image/")){const url=URL.createObjectURL(file);try{const im=new Image();im.src=url;await im.decode();const max=1000,scale=Math.min(1,max/Math.max(im.naturalWidth,im.naturalHeight)),c=document.createElement("canvas");c.width=Math.max(1,Math.round(im.naturalWidth*scale));c.height=Math.max(1,Math.round(im.naturalHeight*scale));c.getContext("2d").drawImage(im,0,0,c.width,c.height);return{data:c.toDataURL("image/jpeg",.72),name:file.name,type:"image/jpeg"}}finally{URL.revokeObjectURL(url)}}return await new Promise((res,rej)=>{const r=new FileReader();r.onload=()=>res({data:r.result,name:file.name,type:file.type||"application/octet-stream"});r.onerror=rej;r.readAsDataURL(file)})}























