async function cfApi(path,options={}){
 const method=options.method||'GET',token=cfToken,key=token+'|'+path;
 const cached=apiShortCache.get(key);if(method==='GET'&&cached&&cached.expires>Date.now())return cached.data;
 if(method==='GET'&&apiInflight.has(key))return apiInflight.get(key);
 const operation=(async()=>{const headers={...(options.headers||{})};if(options.body)headers['Content-Type']='application/json';if(token)headers.Authorization='Bearer '+token;
 const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),25000);
 try{const response=await fetch(CF_API+path,{...options,headers,signal:controller.signal,cache:'no-store'});const data=await response.json().catch(()=>({message:'استجابة الخادم غير صالحة'}));if(!response.ok||data.success===false)throw Object.assign(Error(data.message||'تعذر تنفيذ الطلب'),{status:response.status,code:data.error||data.code});
 if(method!=='GET')apiShortCache.clear();else if(['/api/config','/api/payment-methods'].includes(path))apiShortCache.set(key,{data,expires:Date.now()+30000});return data;
 }catch(e){if(e.name==='AbortError')throw Error('تأخر الاتصال؛ تحقق من الشبكة وأعد المحاولة. لا تُنشئ طلبًا ماليًا جديدًا أثناء التحقق.');throw e}finally{clearTimeout(timer)}})();
 if(method==='GET'){apiInflight.set(key,operation);try{return await operation}finally{if(apiInflight.get(key)===operation)apiInflight.delete(key)}}return operation;
}
function mapLedger(t){
 let meta={};try{meta=JSON.parse(t.metadata_json||'{}')}catch{}
 const kind=['transfer','transfer_in','transfer_out'].includes(t.type)?'transfer':t.direction==='pending_in'?'pending_credit':t.type==='release_balance'?'release_balance':['commission','transfer_fee'].includes(t.type)?'commission':t.type==='admin_balance'?'admin_debit':t.type==='topup'?'topup':t.type;
 const out=['out','admin_out'].includes(t.direction)||Number(t.amount)<0;
 const labels={pending_credit:'تعزيز الرصيد المعلّق',admin_debit:'خصم من الرصيد',release_balance:'تحرير الرصيد المعلّق',commission:'عمولة حوالة',topup:'شحن الرصيد',external_reserve:'حجز حوالة خارجية',external_refund:'رد حوالة خارجية',external_principal:'إيداع حوالة خارجية',external_office_fee:'أجور تسليم حوالة خارجية',external_app_fee:'عمولة حوالة خارجية'};
 return {...t,id:t.id,txId:t.reference_id,from:out?me.id:t.sender_id||'admin',to:out?t.receiver_id||'admin':me.id,fromAccount:t.sender_account, toAccount:t.receiver_account,fromName:t.sender_name||'إدارة الرفاه كاش',toName:t.receiver_name||me.fullname,amount:Math.abs(Number(t.transfer_amount??t.amount)),cur:t.currency,ts:uiTime(t.created_at),type:kind,label:labels[kind]||'حوالة',direction:t.direction,out,fee:Number(t.fee_minor||0)/100,totalDebit:Math.abs(Number(t.total_minor||t.amount_minor||0))/100,meta};
}
function historyQuery(offset=0){const p=new URLSearchParams({limit:'50',offset:String(offset)});if(txFilter.q)p.set('q',txFilter.q);if(txFilter.from)p.set('from',txFilter.from);if(txFilter.to)p.set('to',txFilter.to);return '/api/transactions?'+p}
function assignHistory(tx,append=false){const mapped=(tx.ledger||[]).map(mapLedger);ledgerRows=append?mergeById(ledgerRows,mapped):mapped;ledgerPage=tx.pagination||{};const rows=(tx.transactions||tx.transfers||[]).map(mapTransfer);txs=append?{a:mergeById(txs.a,rows.filter(t=>t.from===me.id)),b:mergeById(txs.b,rows.filter(t=>t.to===me.id))}:{a:rows.filter(t=>t.from===me.id),b:rows.filter(t=>t.to===me.id)};}
function mergeById(a,b){return [...new Map([...a,...b].map(x=>[x.id,x])).values()]}
function transactionRows(){return (ledgerRows.length?ledgerRows:allTx()).slice().sort((a,b)=>b.ts-a.ts||b.id.localeCompare(a.id))}
function updateNoticeBadge(){const b=$('.notification-bell');if(!b)return;b.querySelector('.notification-count')?.remove();if(noticeUnread){const s=document.createElement('span');s.className='notification-count';s.textContent=noticeUnread>99?'99+':noticeUnread;b.appendChild(s)}}
function applyNotices(data){if(noticeMutations)return;const old=userNotificationMap,next={};const incoming=data.notifications||[];const oldest=incoming.length?Math.min(...incoming.map(n=>uiTime(n.created_at))):Infinity;for(const [id,n]of Object.entries(old))if(n.ts<oldest)next[id]=n;for(const n of data.notifications||[]){next[n.id]={...n,text:n.message,title:n.title,ts:uiTime(n.created_at),read:!!n.is_read,txId:n.reference_id||n.transfer_id};if(cfNoticeInitialized&&!old[n.id]&&!n.is_read)notifyVisible(n)}userNotificationMap=next;noticePage=data.pagination||{};noticeUnread=data.unread_count??Object.values(next).filter(n=>!n.read).length;cfNoticeInitialized=true;updateNoticeBadge()}
async function cfRefresh(){
 if(cfRefreshing)return cfRefreshing;if(!cfToken||!me)return;const sid=me.id,token=cfToken,filterAtRefresh=JSON.stringify(txFilter);
 cfRefreshing=(async()=>{const [a,tx,ns,cfg,methods,top]=await Promise.all([cfApi('/api/account'),cfApi(historyQuery()),cfApi('/api/notifications?limit=50'),cfApi('/api/config'),cfApi('/api/payment-methods'),tab==='tx'?cfApi('/api/topups'):Promise.resolve(null)]);
 if(!me||me.id!==sid||token!==cfToken)return;me=mapCfAccount(a);adminAllowed=me.role==='admin'&&me.email.trim().toLowerCase()===ADMIN_EMAIL;if(filterAtRefresh===JSON.stringify(txFilter)){if(tab==='tx'&&ledgerRows.length>50){const oldPage=ledgerPage;assignHistory(tx,true);ledgerPage=oldPage}else assignHistory(tx)}applyNotices(ns);pcfg=cfg.config||{};paymentMethods=methods.methods||[];paymentVersion=methods.version||null;syncPaymentMethods();if(top)tops=(top.topups||[]).map(mapTopup);lastUpdated=Date.now();
 const signature=JSON.stringify([tab,cur,hide,me,ledgerRows,txs,noticeUnread]);if(isAdm&&adminAllowed)await cfAdminLoad(false);else if(isAdm){isAdm=false;render()}else if(signature!==viewSignature){viewSignature=signature;const focus=$('.view input:focus');if(tab==='external'){/* Preserve wizard/settings/identity inputs during account refresh. */}else if(focus&&tab==='tx')refreshTxList();else{const y=$('.view')?.scrollTop||0;animate=false;render();if($('.view'))$('.view').scrollTop=y}}updateNetworkStatus();if(tab==='external'&&typeof externalRefresh==='function')await externalRefresh({quiet:true});
 })().finally(()=>cfRefreshing=null);return cfRefreshing;
}
function txRow(t,i){
 if(t.type==='transfer'){const out=t.from===me.id;return `<div class="tx" data-i="${i}"><div><b>${esc(out?t.toName||t.toAccount:t.fromName||'حوالة واردة')}</b><small>${out?'حوالة صادرة':'حوالة واردة'} • ${esc(t.toAccount||t.fromAccount||'')}</small><small>${new Date(t.ts).toLocaleString('ar')}</small></div><div><b class="${out?'out':'in'}" dir="ltr">${out?'-':'+'}${fmt(t.amount)} ${CS[t.cur]}</b><button class="receipt-open" aria-label="عرض إيصال العملية" onclick="rcFor(${i})">${I('receipt-text',17)}</button></div></div>`}
 const out=t.out||t.type==='admin_debit',pending=t.type==='pending_credit';return `<div class="tx ledger-row" data-i="${i}"><div><b>${esc(t.label)}</b><small>${pending?'إضافة إلى المعلّق — ليست حوالة واردة':t.type==='release_balance'?'نقل من المعلّق إلى المتاح':'عملية رصيد موثقة'}</small><small>${new Date(t.ts).toLocaleString('ar')}</small></div><div><b class="${out?'out':'in'}" dir="ltr">${t.type==='release_balance'?'↔':out?'-':'+'}${fmt(t.amount)} ${CS[t.cur]}</b><button class="receipt-open" aria-label="عرض إيصال العملية" onclick="rcFor(${i})">${I('receipt-text',17)}</button></div></div>`
}
function filteredTx(list){const q=String(txFilter.q||'').trim().toLowerCase();return list.filter(t=>(!q||[t.type,t.reference_id,t.id,t.label,t.fromName,t.toName,t.fromAccount,t.toAccount,t.amount,t.cur].join(' ').toLowerCase().includes(q))&&(!txFilter.from||txDateKey(t.ts)>=txFilter.from)&&(!txFilter.to||txDateKey(t.ts)<=txFilter.to))}
function setTxFilter(k,v){txFilter[k]=v;clearTimeout(txSearchTimer);txSearchTimer=setTimeout(()=>loadHistory(false),250)}
