 const pending=t.type==='pending_credit';window.__adminReceiptData={name:me.fullname,id:accountNo(me),email:me.email,amount:t.amount,cur:t.cur,sign:t.out?-1:1,ts:t.ts,label:t.label,kind:t.type,reference:t.reference_id||t.id};sheet(`<div class="receiptPrint admin-receipt"><div class="receipt-head"><img src="${LOGO_URL}" width="52" height="52" alt="الرفاه كاش"><h2>${esc(t.label)}</h2></div><div class="receipt-table"><div class="receipt-row"><span>المستخدم</span><b>${esc(me.fullname)}</b></div><div class="receipt-row"><span>رقم الحساب</span><b dir="ltr">${esc(accountNo(me))}</b></div><div class="receipt-row"><span>رقم العملية</span><b dir="ltr">${esc(t.reference_id||t.id)}</b></div><div class="receipt-row"><span>التاريخ</span><b>${new Date(t.ts).toLocaleString('ar')}</b></div><div class="receipt-row"><span>الحالة</span><b>${pending?'أضيف إلى الرصيد المعلّق':t.type==='release_balance'?'تم تحرير الرصيد':'عملية مسجلة'}</b></div></div><div class="receipt-total"><strong>${fmt(t.amount)} ${CS[t.cur]}</strong></div>${pending?'<p class="lab">لا يصبح المبلغ متاحًا للتحويل إلا بعد تحريره من الإدارة.</p>':''}<button class="btn" onclick="printAdminReceipt()">حفظ PDF</button><button class="btn g" onclick="sheet(null)">إغلاق</button></div>`)
