async function cfAdminLoad(draw=true){if(!adminAllowed)return;if(cfAdminRefreshing)return cfAdminRefreshing;const sid=me.id;
 const searchSnapshot=aq;cfAdminRefreshing=(async()=>{const [u,t,c,s,m]=await Promise.all([cfApi('/api/admin/users?limit=50&q='+encodeURIComponent(aq)),cfApi('/api/admin/topups'),cfApi('/api/config'),cfApi('/api/admin/support'),cfApi('/api/payment-methods')]);if(me?.id!==sid||!adminAllowed)return;if(searchSnapshot!==aq){setTimeout(()=>cfAdminLoad(true).catch(()=>{}),0);return}adm=(u.users||[]).filter(a=>a.email&&a.status!=='deleted').map(mapCfAccount);adminPage=u.pagination||{};adminSummary=u.summary||null;tp=(t.topups||[]).map(mapTopup);pcfg=c.config||{};paymentMethods=m.methods||[];paymentVersion=m.version||null;syncPaymentMethods();supportInboxCache={};for(const x of (Array.isArray(s.threads)?s.threads:Object.values(s.threads||{})))supportInboxCache[x.user_id||x.id]={...x,fullname:x.name||x.user_name,username:x.account_number,updatedAt:uiTime(x.latest_created_at||x.created_at),lastMessage:x.latest_message||x.message,unreadAdmin:Number(x.unread||0)};
 const sign=JSON.stringify([atab,adm,tp,supportInboxCache]);if(isAdm&&$('#al')){if(draw||sign!==adminSignature){adminSignature=sign;if(['acc','top','support'].includes(atab))alist();else updateAdminBadges()}}})().finally(()=>cfAdminRefreshing=null);return cfAdminRefreshing;
}
