async function openExternal(){if(!me)return;const sid=me.id;try{await loadScript("external.js");if(me?.id!==sid)return;window.__externalReturnAdmin=false;isAdm=false;go("external");await externalOpen()}catch(e){showMessage('تعذر فتح الحوالات الخارجية',e.message)}}
async function openExternalAdmin(){if(!me||!adminAllowed)return;const sid=me.id;try{await loadScript("external.js");if(me?.id!==sid||!adminAllowed)return;window.__externalReturnAdmin=true;isAdm=false;go("external");await externalOpenAdmin()}catch(e){showMessage('تعذر فتح إدارة الحوالات',e.message)}}
function handleExternalBack(){if(tab!=="external")return false;if(typeof externalHandleBack==='function'&&externalHandleBack())return true;if(window.__externalReturnAdmin&&adminAllowed){window.__externalReturnAdmin=false;tab="me";adminView()}else go('home');return true}

bootApp();
